Q: firefox extension: how do i write/update the side bar from firefox extension? A: <p>A sidebar is a DOM document with its own JavaScript. The JS can update the DOM, based on anything you want. The example below doesn't pass messages. It just updates text, but it could add/remove/style elements or whatever you want.</p>
<p><strong>manifest</strong></p>
<pre class="lang-json prettyprint-override"><code>{
  &quot;manifest_version&quot;: 2,
  &quot;name&quot;: &quot;Answer&quot;,
  &quot;description&quot;: &quot;Answer a Stack Overflow question&quot;,
  &quot;version&quot;: &quot;0.1&quot;,
  &quot;content_security_policy&quot;: &quot;default-src 'self'; object-src 'self'&quot;,
  &quot;browser_specific_settings&quot;: {
    &quot;gecko&quot;: {
      &quot;id&quot;: &quot;answer@nanigashi.stackoverflow&quot;
    }
  },
  &quot;sidebar_action&quot;: {
    &quot;default_panel&quot;: &quot;sidebar.htm&quot;
  }
}
</code></pre>
<p><strong>sidebar.htm</strong></p>
<pre class="lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;en&quot;&gt;
  &lt;head&gt;
    &lt;title&gt;Answer&lt;/title&gt;
  &lt;/head&gt;
  &lt;body&gt;
    &lt;script src=&quot;sidebar.js&quot;&gt;&lt;/script&gt;
  &lt;/body&gt;
&lt;/html&gt;
</code></pre>
<p><strong>sidebar.js</strong></p>
<pre class="lang-js prettyprint-override"><code>( function () {
  'use strict';

  const
    body = document.body;

  // change the sidebar html
  function timer() {
    const
      d = Date.now();

    body.textContent = Math.floor( d / 1000 ).toString();
    setTimeout( timer, 1000 - d % 1000 );
  }
  setTimeout( timer );
} () );
</code></pre>

Q: Unpivot data in Google Sheets with Query Function A: <h1>Alternative Option</h1>
<p>Alternatively, you could also take advantage of the built-in scripting in Google Sheets to create a custom <code>=unpivot()</code> formula for a cleaner usage of the formula in your spreadsheet file. Please see the sample script below.</p>
<blockquote>
<p><em>You may follow the steps in <a href="https://developers.google.com/apps-script/guides/sheets/functions#creating_a_custom_function" rel="nofollow noreferrer">creating &amp; saving a custom function in Google Sheet</a>.</em></p>
</blockquote>
<h2><em><strong>[UPDATED]</strong> Sample custom formula script</em></h2>
<pre><code>function unpivot(range) {
  //Filter Person in A, State in E, LA Order in L, LA RTRN in N, HA ORDR in O, HA RTRN in Q, MO ORDR in R, and MO RTRN in T
  const indices = [0, 4, 11, 13, 14, 16, 17, 19];
  range = range.map(row =&gt; row.filter((_, index) =&gt; indices.includes(index)));

  var rawData = range.map((data, index) =&gt; index &gt; 0 &amp;&amp; data.map((x, i) =&gt; i &gt; 1 &amp;&amp; [range[0][i].split(' ')[0], range[0][i].split(' ')[1], x, data[0], data[1]]).filter(x =&gt; x)).filter(y =&gt; y).flat();
  var container = [['Person', 'State', 'Product', 'ORDR', 'RTRN']];
  rawData.forEach((d, i, arr) =&gt; {
    try {
      d[0] == arr[i + 1][0] &amp;&amp; d[3] == arr[i + 1][3] &amp;&amp; d[4] == arr[i + 1][4] &amp;&amp; container.push([d[3], d[4], d[0], d[2], arr[i + 1][2]])
    } catch { }
  });
  return container;
}
</code></pre>
